-- Synthetic portfolio sandbox. Never import an original database export here.
CREATE TABLE academic_years (id serial PRIMARY KEY, year_label varchar(20) UNIQUE NOT NULL, is_active smallint NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE semesters (id serial PRIMARY KEY, academic_year_id integer NOT NULL REFERENCES academic_years(id) ON DELETE CASCADE, name varchar(50) NOT NULL, start_date date NOT NULL, end_date date NOT NULL, is_active smallint NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE courses (id serial PRIMARY KEY, course_code varchar(20) UNIQUE NOT NULL, course_name varchar(100) NOT NULL, units smallint NOT NULL DEFAULT 3, capacity integer NOT NULL DEFAULT 40, description text, is_active smallint NOT NULL DEFAULT 1, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students (id serial PRIMARY KEY, student_no varchar(20) UNIQUE NOT NULL, first_name varchar(50) NOT NULL, middle_name varchar(50), last_name varchar(50) NOT NULL, email varchar(100) UNIQUE NOT NULL, phone varchar(20), birthdate date, gender varchar(10) CHECK (gender IN ('Male','Female','Other')), address text, photo varchar(255) DEFAULT 'default.png', status varchar(20) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive','Graduated','Dropped')), created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enrollments (id serial PRIMARY KEY, student_id integer NOT NULL REFERENCES students(id) ON DELETE CASCADE, course_id integer NOT NULL REFERENCES courses(id) ON DELETE CASCADE, semester_id integer NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, status varchar(20) NOT NULL DEFAULT 'Enrolled' CHECK (status IN ('Enrolled','Dropped','Completed')), enrolled_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, dropped_at timestamp, UNIQUE(student_id,course_id,semester_id));
CREATE TABLE users (id serial PRIMARY KEY, username varchar(50) UNIQUE NOT NULL, password varchar(255) NOT NULL, full_name varchar(100) NOT NULL, email varchar(100) UNIQUE NOT NULL, role varchar(20) NOT NULL DEFAULT 'registrar' CHECK (role IN ('admin','registrar','viewer')), is_active smallint NOT NULL DEFAULT 1, last_login timestamp, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
